const sharedUrl = 'https://mobilvendorcom.sharepoint.com/:f:/s/Onboarding_Mobilvendor/IgCR-1BptbqUT7_ZAVehYyEoAb8xd5aSk4qDHp_C_sKA5fI?e=fTTKRM';

const b64 = Buffer.from(sharedUrl, 'utf8')
  .toString('base64')
  .replace(/\+/g, '-')
  .replace(/\//g, '_')
  .replace(/=+$/g, '');

return [{ json: { shareId: `u!${b64}` } }];

const parentCtx = $items('Set Root Context1')[0].json.__ctx;
const value = $json.value || [];

const enrichedValue = value.map(item => ({
  ...item,
  __parentCtx: parentCtx
}));

return [{ json: { value: enrichedValue, __ctx: parentCtx } }];

function slugify(s) {
  return (s || '')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/ñ/g, 'n').replace(/Ñ/g, 'N')
    .replace(/[^a-zA-Z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
    .toUpperCase();
}

function parseOrderAndName(folderName) {
  const m = (folderName || '').match(/^\s*(\d+)\.\s*(.+)\s*$/);
  if (!m) return { orden: 9999, cleanName: folderName };
  return { orden: parseInt(m[1], 10), cleanName: m[2] };
}

// Buscar primero __parentCtx
const parent = $json.__parentCtx || $json.__ctx || { 
  level: 0, 
  driveId: '', 
  area_id:'', 
  modulo_id:'', 
  topic_id:'', 
  path:'/ONBOARDING' 
};

const x = $json;
const isFolder = !!x.folder;
const name = x.name;

// IMPORTANTE: Asegurar que driveId se preserve
const driveId = parent.driveId || x.parentReference?.driveId || '';

const base = {
  id: x.id,
  name,
  webUrl: x.webUrl,
  isFolder,
  childCount: x.folder?.childCount || 0,
  lastModifiedDateTime: x.lastModifiedDateTime,
  size: x.size || 0,
  level: parent.level + 1,
  path: `${parent.path}/${name}`.replace(/\/+/g, '/'),
  __ctx: { 
    ...parent, 
    driveId: driveId
  }
};

// Level 1 = Area
if (base.level === 1 && isFolder) {
  const area_id = slugify(name);
  base.__ctx = { 
    level: 1, 
    driveId: driveId,
    area_id, 
    modulo_id: '', 
    topic_id: '', 
    path: `/${area_id}` 
  };
}

// Level 2 = Modulo
if (base.level === 2 && isFolder) {
  const { orden, cleanName } = parseOrderAndName(name);
  const modulo_id = `${parent.area_id}__${slugify(cleanName)}`;
  base.mod_orden = orden;
  base.mod_cleanName = cleanName;
  base.__ctx = { 
    level: 2, 
    driveId: driveId,
    area_id: parent.area_id, 
    modulo_id, 
    topic_id: '', 
    path: `${parent.path}/${name}`.replace(/\/+/g, '/') 
  };
}

// Level 3 = Topic
if (base.level === 3 && isFolder) {
  const { orden, cleanName } = parseOrderAndName(name);
  const topic_id = `${parent.modulo_id}__${slugify(cleanName)}`;
  base.top_orden = orden;
  base.top_cleanName = cleanName;
  base.__ctx = { 
    level: 3, 
    driveId: driveId,
    area_id: parent.area_id, 
    modulo_id: parent.modulo_id, 
    topic_id, 
    path: `${parent.path}/${name}`.replace(/\/+/g, '/') 
  };
}

$input.item.json = base;
return $input.item;

// ══════════════════════════════════════════════════════════════
// FIX: Google Sheets devuelve '' en lugar de undefined.
// Identificamos cada tabla por su campo ÚNICO exclusivo:
//   Modulos  → 'parent_modulo_id'  (solo existe en Modulos)
//   Topics   → 'parent_topic_id'   (solo existe en Topics)
//   Recursos → 'doc_id'            (solo existe en Recursos)
// ══════════════════════════════════════════════════════════════

const all = $input.all();

const modulos  = all.filter(i => 'parent_modulo_id' in i.json).map(i => i.json);
const topics   = all.filter(i => 'parent_topic_id'  in i.json).map(i => i.json);
const recursos = all.filter(i => 'doc_id'           in i.json).map(i => i.json);

// ── Diccionario modulo_id → area_id ──────────────────────────
const moduloMap = {};
for (const m of modulos) {
  if (m.modulo_id && m.area_id) moduloMap[m.modulo_id] = m.area_id;
}

// ── Diccionario topic_id → modulo_id ─────────────────────────
const topicMap = {};
for (const t of topics) {
  if (t.topic_id && t.modulo_id) topicMap[t.topic_id] = t.modulo_id;
}

// ── Updates para Topics: rellenar area_id vacío ───────────────
const topicUpdates = topics
  .filter(t => !t.area_id && t.modulo_id && moduloMap[t.modulo_id])
  .map(t => ({ json: {
    topic_id:   t.topic_id,
    modulo_id:  t.modulo_id,
    area_id:    moduloMap[t.modulo_id],
    sp_item_id: t.topic_id
  }}));

// ── Updates para Recursos: rellenar modulo_id y area_id vacíos ─
const recursoUpdates = recursos
  .filter(r => (!r.modulo_id || !r.area_id) && r.topic_id)
  .map(r => {
    const modulo_id = r.modulo_id || topicMap[r.topic_id] || '';
    const area_id   = r.area_id   || moduloMap[modulo_id] || '';
    return { json: {
      doc_id:     r.doc_id,
      topic_id:   r.topic_id,
      modulo_id,
      area_id,
      sp_item_id: r.doc_id
    }};
  });

console.log(`Modulos: ${modulos.length} | Topics: ${topics.length} | Recursos: ${recursos.length}`);
console.log(`Topics a actualizar: ${topicUpdates.length}`);
console.log(`Recursos a actualizar: ${recursoUpdates.length}`);

return [{ json: { topicUpdates, recursoUpdates } }];

